async function backupCreate(job: Job) {
  const server = await loadServer(job);
  if (SANDBOX) {
    await notify(
      server.userId,
      `Backup completed (sandbox) for ${server.hostname}`,
      "Sandbox backup completed (no real VM was touched).",
      `/dashboard/servers/${server.id}`
    );
    return;
  }
  const { conn } = await nodeFor(server);
  const upid = await conn.post(`/nodes/${conn.node}/vzdump`, {
    vmid: server.vmid,
    storage: "backup",
    mode: "snapshot",
    compress: "zstd",
  });
  await conn.waitForTask(upid, 3_600_000);
  await notify(server.userId, `Backup completed for ${server.hostname}`, undefined,
    `/dashboard/servers/${server.id}`);
}

