// ---------------------------------------------------------------------------
// Live task progress (vzdump backup / qmrestore restore)
// ---------------------------------------------------------------------------

/** Minimal shape any progress poller needs — satisfied by `pve` and `pveFor`. */
export type TaskClient = {
  get: (path: string, params?: Record<string, any>) => Promise<any>;
  node: string;
};

export type TaskPhase = "backup" | "restore";

/**
 * Parse the latest completion percentage and a human step out of Proxmox task
 * log lines. vzdump/qmrestore emit lines such as:
 *   "INFO:  42% (4.6 GiB of 11.0 GiB) in 12s, read: ..."
 *   "INFO: status: 42%"
 *   "progress 42% (read 4.6 GiB, ...)"
 *   "INFO: creating vzdump archive '/mnt/backup/...'"
 * Returns the last percentage seen (or null) plus a coarse step label.
 */
export function parseTaskProgress(
  lines: string[],
  phase: TaskPhase
): { pct: number | null; step: string | null } {
  let pct: number | null = null;
  let step: string | null = null;
  const verb = phase === "restore" ? "Restoring archive" : "Creating archive";

  for (const raw of lines) {
    const line = String(raw ?? "");
    const m = line.match(/(\d{1,3})\s*%/);
    if (m) {
      const v = Number(m[1]);
      if (v >= 0 && v <= 100) pct = v;
    }
    const l = line.toLowerCase();
    if (l.includes("creating vzdump archive") || l.includes("starting new backup")) step = "Creating archive";
    else if (l.includes("restore") && (l.includes("start") || l.includes("archive"))) step = "Restoring archive";
    else if (l.includes("uploading") || l.includes("upload")) step = "Uploading to backup pool";
    else if (l.includes("transferred") || l.includes("read:")) step = verb;
    else if (l.includes("finished") || l.includes("finalize") || l.includes("closing")) step = "Finalizing";
  }
  if (pct !== null && step) step = `${step}… ${pct}%`;
  return { pct, step: step ?? (pct !== null ? `${verb}… ${pct}%` : null) };
}

/**
 * Wait for a Proxmox task while streaming live progress. Polls `/status` (to
 * detect completion) and `/tasks/<upid>/log` (for the percentage) every ~2s and
 * invokes `onProgress(progress, step)` on each tick.
 *
 * Progress is monotonic and never regresses. The parsed task percentage (0..100)
 * is mapped into the caller's [base, base+span] window so multi-phase callers
 * (e.g. restore = stop→restore→start) can reserve sub-ranges. When no % has been
 * parsed yet, a coarse time-based creep keeps the bar moving up to a cap.
 */
export async function waitForTaskProgress(
  client: TaskClient,
  upid: string,
  onProgress: (progress: number, step: string) => void | Promise<void>,
  opts: { timeoutMs?: number; phase?: TaskPhase; base?: number; span?: number } = {}
): Promise<void> {
  const timeoutMs = opts.timeoutMs ?? 3_600_000;
  const phase = opts.phase ?? "backup";
  const base = opts.base ?? 0;
  const span = opts.span ?? 100;
  const enc = encodeURIComponent(upid);

  const start = Date.now();
  let reported = base; // last value handed to onProgress (monotonic)
  let creep = 0; // coarse fallback estimate while no % is available

  while (Date.now() - start < timeoutMs) {
    let stopped = false;
    let exitOk = true;

    try {
      const status = await client.get(`/nodes/${client.node}/tasks/${enc}/status`);
      if (status?.status === "stopped") {
        stopped = true;
        exitOk = status.exitstatus === "OK";
      }
    } catch {
      /* transient — try again next tick */
    }

    // Read the log tail and parse the newest percentage/step. Cheap enough for a
    // single VM backup; failures are non-fatal.
    let step: string | null = null;
    let pct: number | null = null;
    try {
      const log = await client.get(`/nodes/${client.node}/tasks/${enc}/log`, { start: 0, limit: 400 });
      const lines: string[] = Array.isArray(log) ? log.map((e: any) => e?.t ?? "") : [];
      const parsed = parseTaskProgress(lines, phase);
      pct = parsed.pct;
      step = parsed.step;
    } catch {
      /* ignore */
    }

    // Compute the target within [base, base+span].
    let target: number;
    if (pct !== null) {
      target = base + (span * pct) / 100;
    } else {
      // Coarse creep: advance slowly toward 85% of the window until a % appears.
      creep = Math.min(creep + 4, 85);
      target = base + (span * creep) / 100;
    }
    if (target > reported) reported = target;

    if (!stopped) {
      await onProgress(Math.round(Math.min(reported, base + span)), step ?? (phase === "restore" ? "Restoring…" : "Creating archive…"));
    }

    if (stopped) {
      if (!exitOk) {
        // Surface the real failure reason from the log tail when available.
        throw new Error(`Proxmox task failed: ${upid}`);
      }
      return;
    }

    await new Promise((r) => setTimeout(r, 2000));
  }
  throw new Error(`Proxmox task timed out: ${upid}`);
}

export async function nextVmid(): Promise<number> {
  const id = await pve.get("/cluster/nextid");
  return Number(id);
}

